// =====================================================================
// SOC-Lite · Decide dedup_count e is_suppressed por grupo de la ventana
// Entrada: merge de
//   · 2 · SELECT ventana 30 min  -> {source_type, rule_id, source_ip, events_in_window, keeper_alert_id, ...}
//   · 3 · SELECT reglas FP       -> {rule_id, fp_pct, total, fp, ...}
// Salida: un ítem por grupo con el SQL de UPDATE ya compilado.
// =====================================================================
const RULES = new Map();
const DEDUP_MAX_COUNT = Number($env.DEDUP_MAX_COUNT || $('C · Set parámetros de ventana').first().json.DEDUP_MAX_COUNT || 25);
const WINDOW = Number($('C · Set parámetros de ventana').first().json.DEDUP_WINDOW_MINUTES || 30);

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.rule_id !== undefined && j.events_in_window === undefined) {
    RULES.set(String(j.rule_id), j);
  }
}

const esc = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
};

const out = [];
for (const item of $input.all()) {
  const g = item.json || {};
  if (g.events_in_window === undefined || !g.rule_id || !g.source_ip) continue;

  const ruleId = String(g.rule_id);
  const ruleInfo = RULES.get(ruleId) || {};
  const fpRate = Number(ruleInfo.fp_pct || 0) / 100;
  const knownNoise = fpRate >= 0.9 && Number(ruleInfo.total || 0) >= 20;
  const highVolume = Number(g.events_in_window) >= DEDUP_MAX_COUNT;
  const suppressed = knownNoise || highVolume;
  const suppressReason = knownNoise
    ? 'Regla ' + ruleId + ' con tasa de FP conocida ' + (fpRate * 100).toFixed(1) + ' % (' + ruleInfo.total + ' triajes)'
    : highVolume
    ? 'Volumen anómalo: ' + g.events_in_window + ' eventos en ' + WINDOW + ' min (umbral ' + DEDUP_MAX_COUNT + ')'
    : null;

  out.push({
    json: {
      source_type: g.source_type,
      rule_id: ruleId,
      source_ip: g.source_ip,
      dest_ip: g.dest_ip,
      events_in_window: Number(g.events_in_window),
      dedup_count: Math.min(Number(g.events_in_window), DEDUP_MAX_COUNT),
      keeper_alert_id: Number(g.keeper_alert_id),
      max_severity: g.max_severity,
      max_rule_level: g.max_rule_level,
      first_seen: g.first_seen,
      last_seen: g.last_seen,
      burst_seconds: g.burst_seconds,
      suppressed: suppressed,
      suppress_reason: suppressReason,
      fp_rate_pct: Number((fpRate * 100).toFixed(2)),
      action: suppressed ? 'suppress' : 'dedup',
      sql: {
        rule_id: esc(ruleId),
        source_type: esc(g.source_type),
        source_ip: esc(g.source_ip),
        dedup_count: Math.min(Number(g.events_in_window), DEDUP_MAX_COUNT),
        is_suppressed: suppressed ? 'TRUE' : 'FALSE',
        keeper_alert_id: Number(g.keeper_alert_id),
        suppress_reason: esc(suppressReason),
        window_minutes: WINDOW
      }
    }
  });
}

if (out.length === 0) {
  // Sin grupos: devuelve el resumen vacío para que el workflow termine limpiamente.
  return [{ json: { groups: 0, action: 'noop', detail: 'Sin grupos de duplicados en la ventana de ' + WINDOW + ' min' } }];
}
return out;
